CREATE OR REPLACE FUNCTION public.get_corretores_intermediacao() RETURNS TABLE(user_id uuid,nome text,cpf text,email text,creci text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'gestor') OR public.has_role(auth.uid(),'diretor')) THEN RETURN; END IF; RETURN QUERY SELECT p.user_id,p.nome,p.cpf,p.email,p.creci FROM public.profiles p WHERE p.user_id IN(SELECT ur.user_id FROM public.user_roles ur WHERE ur.role='corretor') AND p.nome IS NOT NULL ORDER BY p.nome; END $$;
CREATE OR REPLACE FUNCTION public.intermediacao_gerentes() RETURNS TABLE(user_id uuid,nome text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'gestor') OR public.has_role(auth.uid(),'diretor')) THEN RETURN; END IF; RETURN QUERY SELECT DISTINCT p.user_id,p.nome FROM public.profiles p JOIN public.user_roles ur ON ur.user_id=p.user_id WHERE ur.role='gestor' AND p.nome IS NOT NULL ORDER BY p.nome; END $$;
REVOKE ALL ON FUNCTION public.intermediacao_gerentes() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.intermediacao_gerentes() TO authenticated;
CREATE OR REPLACE FUNCTION public.intermediacao_salvar(p_registro jsonb,p_beneficiarios jsonb,p_parcelas jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_id uuid:=(p_registro->>'id')::uuid; v_neg uuid:=NULLIF(p_registro->>'negocio_id','')::uuid; v_lead uuid:=NULLIF(p_registro->>'pipeline_lead_id','')::uuid; v_bruto numeric:=(p_registro->>'valor_bruto')::numeric; v_liquido numeric:=(p_registro->>'valor_liquido')::numeric; v_forma text:=p_registro->>'forma_pagamento'; v_ant public.intermediacoes;
BEGIN
 IF auth.uid() IS NULL OR NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'gestor') OR public.has_role(auth.uid(),'diretor')) THEN RAISE EXCEPTION 'Acesso restrito à gestão.'; END IF;
 IF v_lead IS NULL OR NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'diretor') OR public.can_access_lead(v_lead)) THEN RAISE EXCEPTION 'Vincule a intermediação a um cliente do seu Pipeline.'; END IF;
 IF v_neg IS NOT NULL THEN PERFORM 1 FROM public.negocios WHERE id=v_neg AND pipeline_lead_id=v_lead AND status='ativo' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Negócio não pertence a este cliente.'; END IF; IF EXISTS(SELECT 1 FROM public.negocios WHERE id=v_neg AND fase='ganho' AND intermediacao_id IS NOT NULL) THEN RAISE EXCEPTION 'Preserve o documento de uma venda assinada.'; END IF; END IF;
 IF v_forma IS NULL OR v_forma NOT IN ('pix','zemo','nota_fiscal') OR v_bruto IS NULL OR v_bruto<=0 OR v_bruto::text IN ('NaN','Infinity','-Infinity') OR jsonb_array_length(p_beneficiarios)=0 OR jsonb_array_length(p_parcelas)=0 THEN RAISE EXCEPTION 'Comissão e parcelas inválidas.'; END IF;
 IF ABS((SELECT COALESCE(sum((x->>'valor')::numeric),0) FROM jsonb_array_elements(p_parcelas)x)-v_bruto)>0.01 THEN RAISE EXCEPTION 'A soma das parcelas deve ser igual à comissão bruta.'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_parcelas)x WHERE (x->>'valor')::numeric<=0 OR NULLIF(x->>'vencimento','') IS NULL) THEN RAISE EXCEPTION 'Preencha valor e vencimento das parcelas.'; END IF;
 IF ABS((SELECT COALESCE(sum((x->>'valor_bruto')::numeric),0) FROM jsonb_array_elements(p_beneficiarios)x)-v_bruto)>0.02 OR ABS((SELECT COALESCE(sum((x->>'valor_liquido')::numeric),0) FROM jsonb_array_elements(p_beneficiarios)x)-v_liquido)>0.02 THEN RAISE EXCEPTION 'Confira a divisão da comissão por pessoa.'; END IF;
 IF v_forma='nota_fiscal' AND ((p_registro->>'desconto_nf_pct')::numeric IS DISTINCT FROM 10 OR ABS(v_liquido-round(v_bruto*0.9,2))>0.02) THEN RAISE EXCEPTION 'Nota fiscal desconta dez por cento de todos os beneficiários.'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_beneficiarios)x WHERE (x->>'valor_bruto')::numeric<0 OR (x->>'valor_liquido')::numeric<0 OR ABS((x->>'desconto')::numeric-round((x->>'valor_bruto')::numeric*CASE WHEN v_forma='nota_fiscal' THEN 0.1 ELSE 0 END,2))>0.01) THEN RAISE EXCEPTION 'Divisão financeira inválida.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='intermediacoes' AND name=p_registro->>'arquivo_path') THEN RAISE EXCEPTION 'O documento não foi anexado.'; END IF;
 IF EXISTS(SELECT 1 FROM public.intermediacoes WHERE id=v_id) THEN RETURN v_id; END IF;
 SELECT * INTO v_ant FROM public.intermediacoes WHERE negocio_id=v_neg AND status='ativa' FOR UPDATE;
 IF v_ant.id IS NOT NULL THEN IF v_ant.origem='drive_historico' OR EXISTS(SELECT 1 FROM public.negocios_recebimentos WHERE intermediacao_id=v_ant.id AND status='recebido') THEN RAISE EXCEPTION 'Preserve a intermediação histórica ou com recebimentos confirmados.'; END IF; UPDATE public.intermediacoes SET status='substituida' WHERE id=v_ant.id; UPDATE public.negocios_recebimentos SET status='cancelado',updated_at=now() WHERE intermediacao_id=v_ant.id AND status='pendente'; END IF;
 INSERT INTO public.intermediacoes(id,created_by,comprador_nome,tipo_pessoa,empreendimento,unidade,vgv,valor_comissao,corretores,arquivo_path,filename,payload,forma_pagamento,desconto_nf_pct,negocio_id,pipeline_lead_id,valor_bruto,valor_liquido,parcelas) VALUES(v_id,auth.uid(),p_registro->>'comprador_nome',p_registro->>'tipo_pessoa',p_registro->>'empreendimento',p_registro->>'unidade',(p_registro->>'vgv')::numeric,v_bruto,ARRAY(SELECT jsonb_array_elements_text(p_registro->'corretores')),p_registro->>'arquivo_path',p_registro->>'filename',p_registro->'payload',v_forma,CASE WHEN v_forma='nota_fiscal' THEN 10 ELSE 0 END,v_neg,v_lead,v_bruto,v_liquido,p_registro->'parcelas');
 INSERT INTO public.intermediacao_beneficiarios(intermediacao_id,nome,papel,user_id,percentual,valor_bruto,desconto,valor_liquido) SELECT v_id,x->>'nome',x->>'papel',NULLIF(x->>'user_id','')::uuid,(x->>'percentual')::numeric,(x->>'valor_bruto')::numeric,(x->>'desconto')::numeric,(x->>'valor_liquido')::numeric FROM jsonb_array_elements(p_beneficiarios)x;
 INSERT INTO public.negocios_recebimentos(negocio_id,intermediacao_id,parcela_num,vencimento,valor,forma,created_by) SELECT v_neg,v_id,ord::int,(x->>'vencimento')::date,(x->>'valor')::numeric,v_forma,auth.uid() FROM jsonb_array_elements(p_parcelas) WITH ORDINALITY AS t(x,ord);
 IF v_neg IS NOT NULL THEN UPDATE public.negocios SET intermediacao_id=v_id WHERE id=v_neg; END IF; RETURN v_id;
END $$;
REVOKE ALL ON FUNCTION public.intermediacao_salvar(jsonb,jsonb,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.intermediacao_salvar(jsonb,jsonb,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.intermediacao_preservar_referenciada() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF OLD.origem='drive_historico' OR OLD.negocio_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.negocios WHERE intermediacao_id=OLD.id) OR EXISTS(SELECT 1 FROM public.negocios_recebimentos WHERE intermediacao_id=OLD.id AND status='recebido') THEN RAISE EXCEPTION 'Intermediação histórica ou vinculada deve ser preservada.'; END IF; RETURN OLD; END $$;
CREATE TRIGGER intermediacao_delete_guard BEFORE DELETE ON public.intermediacoes FOR EACH ROW EXECUTE FUNCTION public.intermediacao_preservar_referenciada();
CREATE OR REPLACE FUNCTION public.intermediacao_documento_pode_excluir(p_name text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'gestor') OR public.has_role(auth.uid(),'diretor')) AND NOT EXISTS(SELECT 1 FROM public.intermediacoes i WHERE i.arquivo_path=p_name AND (i.origem='drive_historico' OR i.negocio_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.negocios WHERE intermediacao_id=i.id) OR EXISTS(SELECT 1 FROM public.negocios_recebimentos WHERE intermediacao_id=i.id AND status='recebido'))) $$;
CREATE POLICY intermediacao_documento_preservar ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING(bucket_id<>'intermediacoes' OR public.intermediacao_documento_pode_excluir(name));